package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class FrontChannelLogoutUriVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property front channel logout uri of trusted client ")
  void test_front_channel_logout_uri_v_o_builder() {
    Assertions.assertFalse(
        FrontChannelLogoutUriVO.nullValue().getFrontChannelLogoutUri().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        FrontChannelLogoutUriVO.tryFrom(null).getFrontChannelLogoutUri().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        FrontChannelLogoutUriVO.from("one").getFrontChannelLogoutUri().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> FrontChannelLogoutUriVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", FrontChannelLogoutUriVO.from("one").toString());
  }
}
